const cities = [
        { name: "New York", country: "USA" },
        { name: "Goa", country: "India" },
        {name: "Darjeeling", country: "India"},
        {name: "London", country: "UK"}
    ]

export default function HolidayList(){
    return<>
    <ul>
    {
        cities.sort((a,b)=>{
            return a.countryName === 'India' ? -1 : 1;
        }).map(city=>{
            return <li>{city.name}, {city.country}</li>
        })
    }
    </ul></>
}
